import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = abs(n)
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_a_n(a1):
    a = {1: a1}
    for n in range(1, 7):
        # a_{n+1}=6a_n - 2^{n+2} - 3^{n+1} +5
        a_n = a[n]
        a_n_plus_1 = 6 * a_n - (2**(n+2)) - (3**(n+1)) + 5
        a[n+1] = a_n_plus_1
    return a

a_values = calculate_a_n(10)

print("--- a_n values ---")
for n in range(1, 8):
    print(f"a_{n} = {a_values[n]}")

print("\n--- Prime Factorizations of |a_n| ---")
for n in range(1, 8):
    factors = prime_factorization(a_values[n])
    print(f"|a_{n}| = {a_values[n]}")
    print(f"Factorization: {factors}")

def a_n_mod_7(n):
    # Closed form: a_n = 6^n + 2^n + 3^n - 1
    # Modulo 7: a_n = (-1)^n + 2^n + 3^n - 1 (since 6 = -1 mod 7)

    if n <= 0:
        return None

    mod_6n = pow(6, n, 7)
    mod_2n = pow(2, n, 7)
    mod_3n = pow(3, n, 7)

    return (mod_6n + mod_2n + mod_3n - 1) % 7

# Check for small values of n
results = {}
for n in range(1, 8):
    results[n] = a_n_mod_7(n)

print("n | a_n mod 7")
for n, r in results.items():
    print(f"{n:2} | {r}")
